     1→#ifndef IR_H
     2→#define IR_H
     3→
     4→#include <stdint.h>
     5→#include <stddef.h>
     6→#include "ast.h"
     7→
     8→/* CIR Reference (index into instruction array) */
     9→typedef uint32_t CirRef;
    10→#define CIR_REF_NULL 0
    11→
    12→/* CIR Opcodes (30개) */
    13→typedef enum {
    14→    /* Literal loads */
    15→    CIR_LOAD_INT,
    16→    CIR_LOAD_FLOAT,
    17→    CIR_LOAD_STR,
    18→    CIR_LOAD_VAR,
    19→
    20→    /* Memory operations */
    21→    CIR_STORE_VAR,
    22→    CIR_ADDR_OF,
    23→    CIR_DEREF,
    24→    CIR_INDEX,
    25→    CIR_MEMBER,
    26→
    27→    /* Arithmetic/Logic */
    28→    CIR_BINARY,
    29→    CIR_UNARY,
    30→    CIR_CAST,
    31→
    32→    /* Control flow */
    33→    CIR_LABEL,
    34→    CIR_JMP,
    35→    CIR_JMP_IF,
    36→    CIR_RETURN,
    37→
    38→    /* Functions */
    39→    CIR_FUNC_BEGIN,
    40→    CIR_FUNC_END,
    41→    CIR_CALL,
    42→    CIR_ARG,
    43→
    44→    /* Special */
    45→    CIR_SIZEOF,
    46→    CIR_PHI,
    47→    CIR_NOP,
    48→} CirOpcode;
    49→
    50→/* Individual instruction */
    51→typedef struct {
    52→    CirOpcode op;
    53→    union {
    54→        struct { long long imm; }                              load_int;
    55→        struct { double imm; }                                 load_float;
    56→        struct { uint32_t str_idx; }                           load_str;
    57→        struct { uint32_t name_idx; }                          load_var;
    58→        struct { uint32_t name_idx; CirRef value; }            store_var;
    59→        struct { CirRef operand; }                             addr_of;
    60→        struct { CirRef operand; }                             deref;
    61→        struct { CirRef array; CirRef idx; }                   index;
    62→        struct { CirRef object; int field_idx; }               member;
    63→        struct { int op; CirRef lhs; CirRef rhs; }             binary;
    64→        struct { int op; CirRef operand; }                     unary;
    65→        struct { uint32_t label_id; }                          label;
    66→        struct { uint32_t target; }                            jmp;
    67→        struct { CirRef cond; uint32_t t_label; uint32_t f_label; } jmp_if;
    68→        struct { CirRef value; }                               ret;
    69→        struct { uint32_t name_idx; int param_count; }         func_begin;
    70→        struct { CirRef callee; CirRef *args; int arg_count; } call;
    71→        struct { int arg_idx; }                                arg;
    72→    } u;
    73→} CirInst;
    74→
    75→/* Module (entire program IR) */
    76→typedef struct {
    77→    CirInst  *insts;
    78→    uint32_t  inst_count;
    79→    uint32_t  inst_cap;
    80→
    81→    char    **strings;
    82→    uint32_t  str_count;
    83→    uint32_t  str_cap;
    84→
    85→    uint32_t  next_label;
    86→} CirModule;
    87→
    88→/* AstGen (AST → CIR converter state) */
    89→typedef struct {
    90→    CirModule *module;
    91→
    92→    /* Local variable name → str_idx mapping */
    93→    char     **var_names;
    94→    uint32_t  *var_ids;
    95→    int        var_count;
    96→    int        var_cap;
    97→
    98→    /* break/continue labels */
    99→    uint32_t   break_label;
   100→    uint32_t   continue_label;
   101→} AstGen;
   102→
   103→/* Module operations */
   104→CirModule *cir_module_new(void);
   105→void       cir_module_free(CirModule *m);
   106→void       cir_module_dump(CirModule *m);
   107→
   108→/* String table */
   109→uint32_t   cir_intern_str(CirModule *m, const char *name);
   110→
   111→/* Instruction emission */
   112→CirRef     cir_emit(CirModule *m, CirInst inst);
   113→uint32_t   cir_new_label(CirModule *m);
   114→
   115→/* AstGen operations */
   116→AstGen    *astgen_new(CirModule *m);
   117→void       astgen_free(AstGen *g);
   118→
   119→/* Main entry points */
   120→void       astgen_program(AstGen *g, Node *program);
   121→void       astgen_func(AstGen *g, Node *func_def);
   122→void       astgen_stmt(AstGen *g, Node *stmt);
   123→CirRef     astgen_expr(AstGen *g, Node *expr);
   124→
   125→#endif /* IR_H */
   126→

