     1→#include "ir.h"
     2→#include <stdlib.h>
     3→#include <stdio.h>
     4→#include <string.h>
     5→
     6→/* Module creation */
     7→CirModule *cir_module_new(void) {
     8→    CirModule *m = (CirModule *)malloc(sizeof(CirModule));
     9→    if (!m) return NULL;
    10→
    11→    m->insts = (CirInst *)malloc(sizeof(CirInst) * 1024);
    12→    if (!m->insts) {
    13→        free(m);
    14→        return NULL;
    15→    }
    16→    m->inst_count = 0;
    17→    m->inst_cap = 1024;
    18→
    19→    m->strings = (char **)malloc(sizeof(char *) * 256);
    20→    if (!m->strings) {
    21→        free(m->insts);
    22→        free(m);
    23→        return NULL;
    24→    }
    25→    m->str_count = 0;
    26→    m->str_cap = 256;
    27→
    28→    m->next_label = 0;
    29→    return m;
    30→}
    31→
    32→/* Module deallocation */
    33→void cir_module_free(CirModule *m) {
    34→    if (!m) return;
    35→    if (m->insts) {
    36→        for (uint32_t i = 0; i < m->inst_count; i++) {
    37→            if (m->insts[i].op == CIR_CALL && m->insts[i].u.call.args) {
    38→                free(m->insts[i].u.call.args);
    39→            }
    40→        }
    41→        free(m->insts);
    42→    }
    43→    for (uint32_t i = 0; i < m->str_count; i++) {
    44→        if (m->strings[i]) free(m->strings[i]);
    45→    }
    46→    if (m->strings) free(m->strings);
    47→    free(m);
    48→}
    49→
    50→/* String table intern */
    51→uint32_t cir_intern_str(CirModule *m, const char *name) {
    52→    if (!m || !name) return 0;
    53→    for (uint32_t i = 0; i < m->str_count; i++) {
    54→        if (m->strings[i] && strcmp(m->strings[i], name) == 0) {
    55→            return i;
    56→        }
    57→    }
    58→    if (m->str_count >= m->str_cap) {
    59→        m->str_cap *= 2;
    60→        char **new_strings = (char **)realloc(m->strings, sizeof(char *) * m->str_cap);
    61→        if (!new_strings) return 0;
    62→        m->strings = new_strings;
    63→    }
    64→    m->strings[m->str_count] = (char *)malloc(strlen(name) + 1);
    65→    if (!m->strings[m->str_count]) return 0;
    66→    strcpy(m->strings[m->str_count], name);
    67→    return m->str_count++;
    68→}
    69→
    70→/* Emit instruction */
    71→CirRef cir_emit(CirModule *m, CirInst inst) {
    72→    if (!m) return CIR_REF_NULL;
    73→    if (m->inst_count >= m->inst_cap) {
    74→        m->inst_cap *= 2;
    75→        CirInst *new_insts = (CirInst *)realloc(m->insts, sizeof(CirInst) * m->inst_cap);
    76→        if (!new_insts) return CIR_REF_NULL;
    77→        m->insts = new_insts;
    78→    }
    79→    m->insts[m->inst_count] = inst;
    80→    return m->inst_count++;
    81→}
    82→
    83→/* Allocate new label */
    84→uint32_t cir_new_label(CirModule *m) {
    85→    if (!m) return 0;
    86→    return m->next_label++;
    87→}
    88→
    89→/* AstGen creation */
    90→AstGen *astgen_new(CirModule *m) {
    91→    AstGen *g = (AstGen *)malloc(sizeof(AstGen));
    92→    if (!g) return NULL;
    93→    g->module = m;
    94→    g->var_names = (char **)malloc(sizeof(char *) * 256);
    95→    if (!g->var_names) {
    96→        free(g);
    97→        return NULL;
    98→    }
    99→    g->var_ids = (uint32_t *)malloc(sizeof(uint32_t) * 256);
   100→    if (!g->var_ids) {
   101→        free(g->var_names);
   102→        free(g);
   103→        return NULL;
   104→    }
   105→    g->var_count = 0;
   106→    g->var_cap = 256;
   107→    g->break_label = 0;
   108→    g->continue_label = 0;
   109→    return g;
   110→}
   111→
   112→/* AstGen cleanup */
   113→void astgen_free(AstGen *g) {
   114→    if (!g) return;
   115→    if (g->var_names) free(g->var_names);
   116→    if (g->var_ids) free(g->var_ids);
   117→    free(g);
   118→}
   119→
   120→/* Helper: lookup variable */
   121→static uint32_t astgen_lookup_var(AstGen *g, const char *name) {
   122→    for (int i = 0; i < g->var_count; i++) {
   123→        if (strcmp(g->var_names[i], name) == 0) {
   124→            return g->var_ids[i];
   125→        }
   126→    }
   127→    return cir_intern_str(g->module, name);
   128→}
   129→
   130→/* Expression generation */
   131→CirRef astgen_expr(AstGen *g, Node *expr) {
   132→    if (!expr) return CIR_REF_NULL;
   133→
   134→    switch (expr->kind) {
   135→        case ND_INT_LIT: {
   136→            CirInst inst = {.op = CIR_LOAD_INT, .u.load_int.imm = expr->int_val};
   137→            return cir_emit(g->module, inst);
   138→        }
   139→        case ND_FLOAT_LIT: {
   140→            CirInst inst = {.op = CIR_LOAD_FLOAT, .u.load_float.imm = expr->float_val};
   141→            return cir_emit(g->module, inst);
   142→        }
   143→        case ND_CHAR_LIT: {
   144→            CirInst inst = {.op = CIR_LOAD_INT, .u.load_int.imm = expr->char_val};
   145→            return cir_emit(g->module, inst);
   146→        }
   147→        case ND_STR_LIT: {
   148→            uint32_t str_idx = cir_intern_str(g->module, expr->str_val);
   149→            CirInst inst = {.op = CIR_LOAD_STR, .u.load_str.str_idx = str_idx};
   150→            return cir_emit(g->module, inst);
   151→        }
   152→        case ND_IDENT: {
   153→            uint32_t name_idx = astgen_lookup_var(g, expr->name);
   154→            CirInst inst = {.op = CIR_LOAD_VAR, .u.load_var.name_idx = name_idx};
   155→            return cir_emit(g->module, inst);
   156→        }
   157→        case ND_BINARY: {
   158→            CirRef lhs = astgen_expr(g, expr->left);
   159→            CirRef rhs = astgen_expr(g, expr->right);
   160→            int op_val = 0;
   161→            switch (expr->op) {
   162→                case TK_PLUS: op_val = 0; break;
   163→                case TK_MINUS: op_val = 1; break;
   164→                case TK_STAR: op_val = 2; break;
   165→                case TK_SLASH: op_val = 3; break;
   166→                case TK_PERCENT: op_val = 4; break;
   167→                case TK_LE: op_val = 6; break;
   168→                case TK_GT: op_val = 7; break;
   169→                case TK_GE: op_val = 8; break;
   170→                case TK_EQ: op_val = 12; break;
   171→                case TK_NEQ: op_val = 13; break;
   172→                case TK_LT: op_val = 14; break;
   173→                case TK_AMPERSAND: op_val = 9; break;
   174→                case TK_PIPE: op_val = 10; break;
   175→                case TK_CARET: op_val = 11; break;
   176→                case TK_LSHIFT: op_val = 15; break;
   177→                case TK_RSHIFT: op_val = 16; break;
   178→                case TK_AND: op_val = 18; break;
   179→                case TK_OR: op_val = 19; break;
   180→                default: op_val = 0;
   181→            }
   182→            CirInst inst = {.op = CIR_BINARY, .u.binary = {.op = op_val, .lhs = lhs, .rhs = rhs}};
   183→            return cir_emit(g->module, inst);
   184→        }
   185→        case ND_ASSIGN: {
   186→            CirRef rhs = astgen_expr(g, expr->right);
   187→            if (expr->left->kind == ND_IDENT) {
   188→                uint32_t name_idx = astgen_lookup_var(g, expr->left->name);
   189→                CirInst inst = {.op = CIR_STORE_VAR, .u.store_var = {.name_idx = name_idx, .value = rhs}};
   190→                return cir_emit(g->module, inst);
   191→            }
   192→            return rhs;
   193→        }
   194→        case ND_CALL: {
   195→            CirRef callee = astgen_expr(g, expr->left);
   196→            int arg_count = expr->child_count;
   197→            CirRef *args = NULL;
   198→            if (arg_count > 0) {
   199→                args = (CirRef *)malloc(sizeof(CirRef) * arg_count);
   200→                for (int i = 0; i < arg_count; i++) {
   201→                    args[i] = astgen_expr(g, expr->children[i]);
   202→                }
   203→            }
   204→            CirInst inst = {.op = CIR_CALL, .u.call = {.callee = callee, .args = args, .arg_count = arg_count}};
   205→            return cir_emit(g->module, inst);
   206→        }
   207→        case ND_UNARY: {
   208→            CirRef operand = astgen_expr(g, expr->left);
   209→            int op_val = 0;
   210→            switch (expr->op) {
   211→                case TK_MINUS: op_val = 0; break; /* NEG */
   212→                case TK_BANG: op_val = 1; break;  /* NOT */
   213→                case TK_TILDE: op_val = 2; break; /* BITNOT */
   214→                default: op_val = 0;
   215→            }
   216→            CirInst inst = {.op = CIR_UNARY, .u.unary = {.op = op_val, .operand = operand}};
   217→            return cir_emit(g->module, inst);
   218→        }
   219→        case ND_INDEX: {
   220→            CirRef array = astgen_expr(g, expr->left);
   221→            CirRef idx = astgen_expr(g, expr->right);
   222→            CirInst inst = {.op = CIR_INDEX, .u.index = {.array = array, .idx = idx}};
   223→            return cir_emit(g->module, inst);
   224→        }
   225→        case ND_MEMBER: {
   226→            CirRef object = astgen_expr(g, expr->left);
   227→            CirInst inst = {.op = CIR_MEMBER, .u.member = {.object = object, .field_idx = expr->member_idx}};
   228→            return cir_emit(g->module, inst);
   229→        }
   230→        case ND_ARROW: {
   231→            CirRef ptr = astgen_expr(g, expr->left);
   232→            CirRef deref_inst = cir_emit(g->module, (CirInst){.op = CIR_DEREF, .u.deref.operand = ptr});
   233→            CirInst member_inst = {.op = CIR_MEMBER, .u.member = {.object = deref_inst, .field_idx = expr->member_idx}};
   234→            return cir_emit(g->module, member_inst);
   235→        }
   236→        default:
   237→            return CIR_REF_NULL;
   238→    }
   239→}
   240→
   241→/* Statement generation */
   242→void astgen_stmt(AstGen *g, Node *stmt) {
   243→    if (!stmt) return;
   244→
   245→    switch (stmt->kind) {
   246→        case ND_EXPR_STMT:
   247→            astgen_expr(g, stmt->left);
   248→            break;
   249→        case ND_RETURN: {
   250→            CirRef value = CIR_REF_NULL;
   251→            if (stmt->left) value = astgen_expr(g, stmt->left);
   252→            CirInst ret = {.op = CIR_RETURN, .u.ret.value = value};
   253→            cir_emit(g->module, ret);
   254→            break;
   255→        }
   256→        case ND_BLOCK:
   257→            for (int i = 0; i < stmt->child_count; i++) {
   258→                astgen_stmt(g, stmt->children[i]);
   259→            }
   260→            break;
   261→        case ND_VAR_DECL: {
   262→            uint32_t name_idx = cir_intern_str(g->module, stmt->name);
   263→            if (g->var_count >= g->var_cap) {
   264→                g->var_cap *= 2;
   265→                char **new_names = (char **)realloc(g->var_names, sizeof(char *) * g->var_cap);
   266→                uint32_t *new_ids = (uint32_t *)realloc(g->var_ids, sizeof(uint32_t) * g->var_cap);
   267→                if (new_names) g->var_names = new_names;
   268→                if (new_ids) g->var_ids = new_ids;
   269→            }
   270→            g->var_names[g->var_count] = stmt->name;
   271→            g->var_ids[g->var_count] = name_idx;
   272→            g->var_count++;
   273→            if (stmt->left) {
   274→                CirRef value = astgen_expr(g, stmt->left);
   275→                CirInst inst = {.op = CIR_STORE_VAR, .u.store_var = {.name_idx = name_idx, .value = value}};
   276→                cir_emit(g->module, inst);
   277→            }
   278→            break;
   279→        }
   280→        case ND_IF: {
   281→            CirRef cond_ref = astgen_expr(g, stmt->cond);
   282→            uint32_t t_label = cir_new_label(g->module);
   283→            uint32_t f_label = cir_new_label(g->module);
   284→            uint32_t end_label = cir_new_label(g->module);
   285→            CirInst jmp_if = {.op = CIR_JMP_IF, .u.jmp_if = {.cond = cond_ref, .t_label = t_label, .f_label = f_label}};
   286→            cir_emit(g->module, jmp_if);
   287→            CirInst label_t = {.op = CIR_LABEL, .u.label.label_id = t_label};
   288→            cir_emit(g->module, label_t);
   289→            if (stmt->then_body) astgen_stmt(g, stmt->then_body);
   290→            CirInst jmp_end = {.op = CIR_JMP, .u.jmp.target = end_label};
   291→            cir_emit(g->module, jmp_end);
   292→            CirInst label_f = {.op = CIR_LABEL, .u.label.label_id = f_label};
   293→            cir_emit(g->module, label_f);
   294→            if (stmt->else_body) {
   295→                astgen_stmt(g, stmt->else_body);
   296→                jmp_end = (CirInst){.op = CIR_JMP, .u.jmp.target = end_label};
   297→                cir_emit(g->module, jmp_end);
   298→            }
   299→            CirInst label_end = {.op = CIR_LABEL, .u.label.label_id = end_label};
   300→            cir_emit(g->module, label_end);
   301→            break;
   302→        }
   303→        case ND_WHILE: {
   304→            uint32_t cond_label = cir_new_label(g->module);
   305→            uint32_t body_label = cir_new_label(g->module);
   306→            uint32_t end_label = cir_new_label(g->module);
   307→            uint32_t old_break = g->break_label;
   308→            uint32_t old_continue = g->continue_label;
   309→            g->break_label = end_label;
   310→            g->continue_label = cond_label;
   311→            CirInst label_cond = {.op = CIR_LABEL, .u.label.label_id = cond_label};
   312→            cir_emit(g->module, label_cond);
   313→            CirRef cond_ref = astgen_expr(g, stmt->cond);
   314→            CirInst jmp_if = {.op = CIR_JMP_IF, .u.jmp_if = {.cond = cond_ref, .t_label = body_label, .f_label = end_label}};
   315→            cir_emit(g->module, jmp_if);
   316→            CirInst label_body = {.op = CIR_LABEL, .u.label.label_id = body_label};
   317→            cir_emit(g->module, label_body);
   318→            if (stmt->body) astgen_stmt(g, stmt->body);
   319→            CirInst jmp_cond = {.op = CIR_JMP, .u.jmp.target = cond_label};
   320→            cir_emit(g->module, jmp_cond);
   321→            CirInst label_end = {.op = CIR_LABEL, .u.label.label_id = end_label};
   322→            cir_emit(g->module, label_end);
   323→            g->break_label = old_break;
   324→            g->continue_label = old_continue;
   325→            break;
   326→        }
   327→        case ND_FOR: {
   328→            if (stmt->init) astgen_stmt(g, stmt->init);
   329→            uint32_t cond_label = cir_new_label(g->module);
   330→            uint32_t body_label = cir_new_label(g->module);
   331→            uint32_t end_label = cir_new_label(g->module);
   332→            uint32_t old_break = g->break_label;
   333→            uint32_t old_continue = g->continue_label;
   334→            g->break_label = end_label;
   335→            g->continue_label = cond_label;
   336→            CirInst label_cond = {.op = CIR_LABEL, .u.label.label_id = cond_label};
   337→            cir_emit(g->module, label_cond);
   338→            if (stmt->cond) {
   339→                CirRef cond_ref = astgen_expr(g, stmt->cond);
   340→                CirInst jmp_if = {.op = CIR_JMP_IF, .u.jmp_if = {.cond = cond_ref, .t_label = body_label, .f_label = end_label}};
   341→                cir_emit(g->module, jmp_if);
   342→            } else {
   343→                CirInst jmp = {.op = CIR_JMP, .u.jmp.target = body_label};
   344→                cir_emit(g->module, jmp);
   345→            }
   346→            CirInst label_body = {.op = CIR_LABEL, .u.label.label_id = body_label};
   347→            cir_emit(g->module, label_body);
   348→            if (stmt->body) astgen_stmt(g, stmt->body);
   349→            if (stmt->step) astgen_expr(g, stmt->step);
   350→            CirInst jmp_cond = {.op = CIR_JMP, .u.jmp.target = cond_label};
   351→            cir_emit(g->module, jmp_cond);
   352→            CirInst label_end = {.op = CIR_LABEL, .u.label.label_id = end_label};
   353→            cir_emit(g->module, label_end);
   354→            g->break_label = old_break;
   355→            g->continue_label = old_continue;
   356→            break;
   357→        }
   358→        case ND_BREAK: {
   359→            CirInst jmp = {.op = CIR_JMP, .u.jmp.target = g->break_label};
   360→            cir_emit(g->module, jmp);
   361→            break;
   362→        }
   363→        case ND_CONTINUE: {
   364→            CirInst jmp = {.op = CIR_JMP, .u.jmp.target = g->continue_label};
   365→            cir_emit(g->module, jmp);
   366→            break;
   367→        }
   368→        default:
   369→            break;
   370→    }
   371→}
   372→
   373→/* Function generation */
   374→void astgen_func(AstGen *g, Node *func_def) {
   375→    if (!func_def || func_def->kind != ND_FUNC_DEF) return;
   376→    uint32_t name_idx = cir_intern_str(g->module, func_def->name);
   377→    int param_count = func_def->child_count;
   378→    CirInst func_begin = {.op = CIR_FUNC_BEGIN, .u.func_begin = {.name_idx = name_idx, .param_count = param_count}};
   379→    cir_emit(g->module, func_begin);
   380→    if (func_def->body) astgen_stmt(g, func_def->body);
   381→    CirInst func_end = {.op = CIR_FUNC_END};
   382→    cir_emit(g->module, func_end);
   383→}
   384→
   385→/* Program generation */
   386→void astgen_program(AstGen *g, Node *program) {
   387→    if (!program || program->kind != ND_PROGRAM) return;
   388→    for (int i = 0; i < program->child_count; i++) {
   389→        Node *decl = program->children[i];
   390→        if (decl && decl->kind == ND_FUNC_DEF) {
   391→            astgen_func(g, decl);
   392→        }
   393→    }
   394→}
