    37→/* Initialization */
    38→Codegen *codegen_new(CirModule *m, FILE *out) {
    39→    if (!m || !out) return NULL;
    40→    Codegen *cg = (Codegen *)malloc(sizeof(Codegen));
    41→    if (!cg) return NULL;
    42→    cg->out = out;
    43→    cg->module = m;
    44→    cg->ref_offsets = (int *)malloc(sizeof(int) * m->inst_count);
    45→    if (!cg->ref_offsets) { free(cg); return NULL; }
    46→    cg->ref_count = 0;
    47→    cg->var_name_idx = (uint32_t *)malloc(sizeof(uint32_t) * 256);
    48→    cg->var_offsets = (int *)malloc(sizeof(int) * 256);
    49→    if (!cg->var_name_idx || !cg->var_offsets) {
    50→        free(cg->ref_offsets);
    51→        free(cg->var_name_idx);
    52→        free(cg->var_offsets);
    53→        free(cg);
    54→        return NULL;
    55→    }
    56→    cg->var_count = 0;
    57→    cg->var_cap = 256;
    58→    cg->func_start = 0;
    59→    cg->func_end = 0;
    60→    cg->stack_size = 0;
    61→    return cg;
    62→}
    63→
    64→void codegen_free(Codegen *cg) {
    65→    if (!cg) return;
    66→    free(cg->ref_offsets);
    67→    free(cg->var_name_idx);
    68→    free(cg->var_offsets);
    69→    free(cg);
    70→}
    71→
    72→/* Offset allocation */
    73→static int alloc_ref_offset(Codegen *cg) {
    74→    if (cg->ref_count >= cg->module->inst_count) return 0;
    75→    int offset = -(8 + cg->ref_count * 8);
    76→    cg->ref_offsets[cg->ref_count] = offset;
    77→    return cg->ref_count++;
    78→}
    79→
    80→static int get_var_offset(Codegen *cg, uint32_t name_idx) {
    81→    for (int i = 0; i < cg->var_count; i++) {
    82→        if (cg->var_name_idx[i] == name_idx) {
    83→            return cg->var_offsets[i];
    84→        }
    85→    }
    86→    /* 새로운 변수 */
    87→    if (cg->var_count >= cg->var_cap) return 0;
    88→    cg->var_name_idx[cg->var_count] = name_idx;
    89→    int offset = -(8 + cg->ref_count * 8 + cg->var_count * 8);
    90→    cg->var_offsets[cg->var_count] = offset;
    91→    cg->var_count++;
    92→    if (offset < cg->stack_size) cg->stack_size = offset;
    93→    return offset;
    94→}
