     9→/* Helper: parse code string to AST, then generate CIR */
    10→static CirModule *ir_from_string(const char *code) {
    11→    Lexer *lexer = lexer_new(code, strlen(code));
    12→    if (!lexer) return NULL;
    13→    lexer_tokenize(lexer);
    14→
    15→    Parser *parser = parser_new(lexer);
    16→    if (!parser) {
    17→        lexer_free(lexer);
    18→        return NULL;
    19→    }
    20→
    21→    Node *ast = parse_program(parser);
    22→    parser_free(parser);
    23→    lexer_free(lexer);
    24→
    25→    if (!ast) return NULL;
    26→
    27→    CirModule *module = cir_module_new();
    28→    if (!module) {
    29→        node_free_recursive(ast);
    30→        return NULL;
    31→    }
    32→
    33→    AstGen *gen = astgen_new(module);
    34→    if (!gen) {
    35→        cir_module_free(module);
    36→        node_free_recursive(ast);
    37→        return NULL;
    38→    }
    39→
    40→    astgen_program(gen, ast);
    41→    astgen_free(gen);
    42→    node_free_recursive(ast);
    43→
    44→    return module;
    45→}
